@push('styles')
<style>
:root{--bg:#F5EBE6;--paper:#FCF8F5;--ink:#5E4636;--soft:#8C6E5C;--copper:#C78E66;--deep:#A8714E;--line:#E6D3C6;--board:#3A2C24;--tile:#241B16;--tile-ink:#F4E8DC;--acc:#E2AE84;--shadow:rgba(120,80,55,.2);
--sans:var(--font-sans);--serif:var(--font-serif);
box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#211915;--paper:#2C231F;--ink:#EEDFD4;--soft:#BFA493;--copper:#D9A47E;--deep:#E2B28E;--line:#433630;--shadow:rgba(0,0,0,.45);--board:#16100D;--tile:#0E0A08}}
:root[data-theme="dark"]{--bg:#211915;--paper:#2C231F;--ink:#EEDFD4;--soft:#BFA493;--copper:#D9A47E;--deep:#E2B28E;--line:#433630;--shadow:rgba(0,0,0,.45);--board:#16100D;--tile:#0E0A08}
*,*::before,*::after{box-sizing:inherit}
html{scroll-behavior:smooth;scroll-padding-top:calc(env(safe-area-inset-top,0px) + 80px)}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit}
.wrap{max-width:1240px;margin:0 auto;padding:0 clamp(1.1rem,4vw,3rem)}
.eyebrow{font-size:.78rem;letter-spacing:.28em;color:var(--deep);display:flex;align-items:center;gap:.9rem;margin:0 0 .8rem}
.eyebrow::after{content:"";width:56px;height:1.5px;background:currentColor}
.center .eyebrow{justify-content:center}.center .eyebrow::before{content:"";width:56px;height:1.5px;background:currentColor}
h2.t{margin:0;font-weight:600;font-size:clamp(1.7rem,3vw,2.5rem);color:var(--copper);text-transform:uppercase;letter-spacing:.01em;line-height:1.1}
.sub{font-family:var(--serif);font-style:italic;color:var(--deep);margin:.7rem 0 0;font-size:1.02rem;line-height:1.6;max-width:38em}
.center{text-align:center}.center .sub{margin-left:auto;margin-right:auto}
section{padding:clamp(3rem,7vw,5.5rem) 0}
.btn{display:inline-flex;align-items:center;gap:.5rem;font:inherit;font-size:.95rem;font-weight:600;text-decoration:none;border-radius:999px;padding:.85rem 1.4rem;cursor:pointer;border:1.5px solid var(--copper);transition:transform .2s,background .2s}
.btn.primary{background:var(--copper);color:#fff}.btn.ghost{color:var(--deep);background:transparent}
.btn:hover{transform:translateY(-2px)}.btn:focus-visible{outline:2px solid var(--deep);outline-offset:3px}
/* header */
header.nav{position:sticky;top:0;z-index:50;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);padding-top:env(safe-area-inset-top,0px)}
.nav .wrap{display:flex;align-items:center;justify-content:space-between;height:72px;gap:1rem}
.nav img{height:38px;width:auto}
.nav ul{display:flex;gap:clamp(1rem,2.5vw,2.2rem);list-style:none;margin:0;padding:0;font-size:.95rem}
.nav ul a{text-decoration:none;color:var(--ink);padding:.4rem 0;border-bottom:1.5px solid transparent}
.nav ul a[aria-current]{border-color:var(--copper)}.nav ul a:hover{color:var(--copper)}
.icons{display:flex;gap:1rem}.icons a{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;color:var(--ink)}.icons a:hover{background:var(--paper)}
.icons svg{width:20px;height:20px}
/* hero */
.hero{position:relative;height:auto;min-height:0;max-height:none;overflow:visible;background:var(--bg);padding:clamp(2rem,5vw,4rem) 0 clamp(3rem,6vw,5rem)}
.hero .wrap{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(2rem,4vw,4rem);align-items:center}
.hero h1{margin:0;font-weight:600;color:var(--copper);font-size:clamp(2.1rem,4vw,3.5rem);line-height:1.04;text-transform:uppercase;letter-spacing:.005em}
.hero h1 em{font-family:var(--serif);font-style:italic;font-weight:400;text-transform:none;color:var(--deep);display:block;font-size:.62em;margin-top:.5rem;letter-spacing:0}
.hero p.lead{font-family:var(--serif);color:var(--soft);font-size:1.08rem;line-height:1.75;max-width:32em;margin:1.3rem 0 1.8rem}
.ctas{display:flex;gap:.8rem;flex-wrap:wrap}
.trust{display:flex;gap:1.5rem;flex-wrap:wrap;margin-top:2rem;font-size:.82rem;color:var(--soft);letter-spacing:.04em}.trust b{color:var(--copper);font-size:1.4rem;display:block;font-weight:600}
.stage{position:relative;min-width:0}
.hero-img{border-radius:240px 240px 26px 26px;overflow:hidden;aspect-ratio:.82;box-shadow:0 40px 80px -40px var(--shadow);max-width:470px;margin-left:auto;outline:1.5px solid var(--copper);outline-offset:12px}
.hero-img img{width:100%;height:100%;object-fit:cover;transition:opacity .35s ease}
.board{position:absolute;left:0;bottom:-26px;width:min(440px,92%);background:var(--board);border-radius:18px;padding:1rem 1rem .8rem;box-shadow:0 30px 60px -24px rgba(0,0,0,.45)}
.bh{display:flex;justify-content:space-between;color:var(--acc);font-weight:600;letter-spacing:.18em;font-size:.72rem;margin-bottom:.6rem}.bh time{color:#BFA493}
.brow{display:grid;grid-template-columns:auto 1fr auto;gap:.7rem;align-items:center;padding:.45rem .2rem;border-top:1px solid rgba(226,174,132,.14);text-decoration:none;color:var(--tile-ink);border-radius:8px}
.brow:hover,.brow:focus-visible,.brow.is-active{background:rgba(226,174,132,.08);outline:none}
.cells{display:flex;gap:2px}.f{width:15px;height:22px;background:var(--tile);border-radius:3px;display:grid;place-items:center;font-size:.68rem;font-weight:600;color:var(--tile-ink);position:relative;overflow:hidden}
.f::after{content:"";position:absolute;left:0;right:0;top:50%;height:1px;background:#0A0705}
.fl{font-family:var(--serif);font-size:.9rem;color:#E9D9CB;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.st{font-size:.66rem;letter-spacing:.12em;font-weight:600;border-radius:999px;padding:.25rem .55rem;white-space:nowrap}
.st.landed{background:rgba(154,160,122,.25);color:#C9D1A4}.st.flying{background:rgba(226,174,132,.2);color:var(--acc)}.st.pre{background:rgba(201,179,218,.2);color:#D9C8E6}
/* new arrivals */
.prods{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(.9rem,2vw,1.4rem);margin-top:2.4rem}
.card{position:relative;text-decoration:none;color:inherit;display:block}
.ph{position:relative;border-radius:22px;overflow:hidden;aspect-ratio:.8;background:var(--paper)}
.ph img{width:100%;height:100%;object-fit:cover;transition:transform .6s}.card:hover .ph img{transform:scale(1.04)}
.badge{position:absolute;left:12px;top:12px;font-size:.7rem;font-weight:600;letter-spacing:.12em;padding:.35rem .6rem;border-radius:999px;background:var(--paper);color:var(--deep)}
.tag{position:absolute;right:-6px;top:26px;transform:rotate(8deg);background:var(--paper);border-radius:6px 8px 8px 6px;padding:.35rem .6rem .35rem 1.1rem;font-size:.72rem;font-weight:600;letter-spacing:.1em;color:var(--copper);box-shadow:0 8px 16px -8px rgba(0,0,0,.35)}
.tag::before{content:"";position:absolute;left:.4rem;top:50%;width:6px;height:6px;margin-top:-3px;border-radius:50%;background:var(--copper)}
.card h3{margin:.9rem 0 .15rem;font-size:1.05rem;font-weight:600}.card p{margin:0;font-family:var(--serif);font-style:italic;color:var(--soft);font-size:.9rem}
/* collections */
.cols{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:220px;gap:clamp(.8rem,1.6vw,1.2rem);margin-top:2.4rem}
.col{position:relative;border-radius:22px;overflow:hidden;text-decoration:none;color:#fff;display:block}
.col.big{grid-column:span 2;grid-row:span 2}
.col img{width:100%;height:100%;object-fit:cover;transition:transform .6s}.col:hover img{transform:scale(1.05)}
.col::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgba(40,26,20,.7))}
.col .info{position:absolute;left:1.1rem;bottom:1rem;z-index:1}.col h3{margin:0;font-size:1.15rem;font-weight:600;letter-spacing:.02em}.col.big h3{font-size:1.6rem}
.col small{font-family:var(--serif);font-style:italic;font-size:.88rem;opacity:.9}
.stamp{position:absolute;right:14px;top:14px;z-index:1;width:64px;height:64px;border-radius:50%;display:grid;place-items:center;font-weight:600;font-size:.82rem;letter-spacing:.06em;color:#fff;border:2px solid rgba(255,255,255,.85);transform:rotate(-10deg);backdrop-filter:blur(2px);background:rgba(199,142,102,.35)}
.stamp::before{content:"";position:absolute;inset:4px;border-radius:50%;border:1px dashed rgba(255,255,255,.7)}
.col:focus-visible{outline:2px solid var(--deep);outline-offset:3px}
/* promise ticket */
.ticket{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) 180px;background:var(--paper);border:1px solid var(--line);border-radius:26px;overflow:hidden;box-shadow:0 30px 60px -40px var(--shadow)}
.tk{padding:1.6rem 1.6rem 1.5rem;border-right:1.5px dashed var(--line)}
.tk small{display:block;font-size:.68rem;letter-spacing:.2em;color:var(--soft);margin-bottom:.4rem}
.tk b{display:block;font-size:1.25rem;color:var(--copper);font-weight:600;margin-bottom:.4rem}
.tk p{margin:0;font-family:var(--serif);color:var(--soft);font-size:.92rem;line-height:1.6}
.tk.stub{border-right:0;background:var(--board);color:var(--tile-ink);display:grid;place-items:center;text-align:center;gap:.3rem}
.tk.stub b{color:var(--acc);font-size:1.6rem;margin:0}.tk.stub small{color:#BFA493;margin:0}
.bars{display:flex;gap:2px;height:44px;margin-top:.5rem}.bars i{background:var(--tile-ink);opacity:.85}
/* map */
.mapsec{background:var(--paper);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.mapsec .wrap{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.5fr);gap:clamp(2rem,4vw,4rem);align-items:center}
.mapsec svg{width:100%;height:auto;display:block}
.land{fill:#DEC3AF}.arc{fill:none;stroke:var(--copper);stroke-width:2;stroke-dasharray:1;stroke-dashoffset:1;opacity:.75}
.mapsec.in .arc{animation:draw 1.8s cubic-bezier(.6,.05,.3,1) forwards;animation-delay:var(--d)}
@keyframes draw{to{stroke-dashoffset:0}}
.pdot{fill:var(--paper);stroke:var(--copper);stroke-width:3}.hn{fill:var(--copper)}.hn-ring{fill:none;stroke:var(--copper);stroke-width:2;transform-box:fill-box;transform-origin:center;animation:pulse 2.4s ease-out infinite}
@keyframes pulse{from{transform:scale(.7);opacity:.9}to{transform:scale(2.6);opacity:0}}
.hnt{font-family:var(--sans);font-weight:600;font-size:26px;fill:var(--ink)}
.stats{display:flex;gap:0;margin:1.6rem 0 1.8rem}.stats div{flex:1;padding:0 1rem;border-left:1.5px solid var(--line)}.stats div:first-child{padding-left:0;border-left:0}
.stats b{display:block;font-size:2.2rem;color:var(--copper);font-weight:600;line-height:1}.stats span{display:block;margin-top:.4rem;font-size:.72rem;letter-spacing:.12em;color:var(--soft);text-transform:uppercase}
/* mystery */
.mystery .wrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(2rem,4vw,4rem);align-items:center}
.mtk{position:relative;background:var(--paper);border:1px solid var(--line);border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -36px var(--shadow);transform:rotate(-2deg)}
.mtk .h{background:var(--board);color:var(--acc);letter-spacing:.2em;font-weight:600;font-size:.8rem;padding:1rem 1.3rem}
.mtk .bd{padding:1.2rem 1.3rem 1.3rem}
.route{display:flex;align-items:center;gap:.8rem;font-size:1.8rem;font-weight:600;color:var(--copper)}.route i{flex:1;border-top:2px dashed var(--copper);opacity:.6}
.scratch{position:relative;margin-top:1rem;border-radius:14px;overflow:hidden;height:150px;touch-action:none}
.scratch .under{position:absolute;inset:0;display:grid;grid-template-columns:150px 1fr;align-items:center;gap:1rem;background:var(--bg)}
.scratch .under img{width:150px;height:150px;object-fit:cover}
.scratch .under p{margin:0;font-family:var(--serif);font-style:italic;color:var(--deep);font-size:1.05rem;line-height:1.5;padding-right:1rem}
.scratch canvas{position:absolute;inset:0;width:100%;height:100%;cursor:grab}
.hint{font-size:.82rem;color:var(--soft);margin:.6rem 0 0}
/* journal */
.mags{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(1rem,2vw,1.6rem);margin-top:2.4rem}
.mag{display:block;text-decoration:none;color:inherit;background:var(--paper);border:1px solid var(--line);border-radius:6px;padding:14px 14px 18px;box-shadow:0 20px 40px -30px var(--shadow);transition:transform .3s}
.mag:hover{transform:translateY(-4px) rotate(-.6deg)}
.mag .mh{text-align:center;font-weight:600;letter-spacing:.24em;color:var(--copper);font-size:1rem;margin:.2rem 0 .1rem}.mag .mi{text-align:center;font-size:.62rem;letter-spacing:.18em;color:var(--soft);margin-bottom:.7rem}
.mag img{width:100%;aspect-ratio:.75;object-fit:cover}
.mag h3{margin:.9rem 0 .2rem;font-family:var(--serif);font-weight:500;font-size:1.2rem;color:var(--ink)}.mag p{margin:0;font-size:.85rem;color:var(--soft)}
.more{text-align:center;margin-top:2rem}
/* windows */
.wins{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:clamp(.8rem,2vw,1.4rem);margin-top:2.4rem;background:#EFE6DE;border-radius:34px;padding:clamp(1.2rem,3vw,2.2rem)}
.win{border-radius:999px;padding:10px;background:#E4D7CB;box-shadow:inset 0 2px 6px rgba(90,60,40,.25)}
.win img{border-radius:999px;aspect-ratio:.7;width:100%;object-fit:cover;box-shadow:inset 0 0 20px rgba(0,0,0,.3)}
.wins figcaption{font-size:.7rem;letter-spacing:.14em;text-align:center;color:var(--soft);margin-top:.6rem}
/* b2b */
.b2b{background:var(--board);color:var(--tile-ink);border-radius:30px;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:clamp(1.2rem,3vw,2.4rem);align-items:center;padding:clamp(1.4rem,3vw,2.2rem)}
.b2b img{width:120px;height:120px;border-radius:50%;object-fit:cover;outline:2px solid var(--acc);outline-offset:5px}
.b2b small{letter-spacing:.22em;color:var(--acc);font-weight:600;font-size:.74rem}.b2b h2{margin:.3rem 0 .4rem;font-size:clamp(1.4rem,2.6vw,2rem);text-transform:uppercase;color:#F4E8DC;font-weight:600}
.b2b p{margin:0;font-family:var(--serif);font-style:italic;color:#CDB5A2}
.b2b .btn.primary{background:var(--acc);border-color:var(--acc);color:#2A1F19}
/* footer */
footer{border-top:1px solid var(--line);padding:3rem 0 2.4rem;margin-top:3rem}
footer .wrap{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:2rem}
footer .tl{font-family:var(--serif);font-style:italic;color:var(--deep);font-size:1.1rem;margin:.8rem 0}
footer h4{margin:0 0 .8rem;font-size:.74rem;letter-spacing:.22em;color:var(--copper)}
footer ul{list-style:none;margin:0;padding:0;display:grid;gap:.5rem;font-size:.92rem}footer ul a{text-decoration:none;color:var(--soft)}footer ul a:hover{color:var(--copper)}
footer .gate{display:inline-block;font-size:.66rem;font-weight:600;color:#fff;background:var(--copper);border-radius:5px;padding:.15rem .35rem;margin-right:.5rem;letter-spacing:.08em}
.copy{text-align:center;color:var(--soft);font-size:.8rem;margin-top:2.4rem}
.reveal{opacity:0;transform:translateY(18px);transition:opacity .8s,transform .8s}.reveal.in{opacity:1;transform:none}
@media (max-width:980px){.hero .wrap,.mapsec .wrap,.mystery .wrap{grid-template-columns:1fr}.prods{grid-template-columns:repeat(2,minmax(0,1fr))}
.cols{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:180px}.ticket{grid-template-columns:1fr}.tk{border-right:0;border-bottom:1.5px dashed var(--line)}
.mags{grid-template-columns:1fr 1fr}.wins{grid-template-columns:repeat(3,minmax(0,1fr))}.wins figure:nth-child(n+4){display:none}
.b2b{grid-template-columns:1fr;text-align:center;justify-items:center}footer .wrap{grid-template-columns:1fr}.nav ul{display:none}.board{position:relative;bottom:auto;margin-top:-60px;width:100%}.hero-img{margin:0 auto}}
@media (max-width:560px){.mags{grid-template-columns:1fr}.scratch .under{grid-template-columns:110px 1fr}.scratch .under img{width:110px}}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}.arc{stroke-dashoffset:0}}
.holiday-shortcuts{max-width:760px;margin:0 auto;padding:2.4rem 1.1rem 3rem;font-family:"Josefin Sans",var(--font-sans),sans-serif;color:#5E4636}.holiday-shortcuts__eyebrow{display:flex;align-items:center;justify-content:center;gap:1rem;letter-spacing:.32em;font-size:.82rem;color:#A8714E}.holiday-shortcuts__eyebrow::before,.holiday-shortcuts__eyebrow::after{content:"";width:56px;height:1.5px;background:currentColor}.holiday-shortcuts h2{margin:.7rem 0 1.6rem;text-align:center;font-family:"Lora",var(--font-serif),serif;font-weight:500;font-size:clamp(1.7rem,6vw,2.3rem);color:#C78E66;letter-spacing:.02em;text-transform:uppercase}.holiday-shortcuts__grid{display:grid;grid-template-columns:1fr 1fr;gap:.9rem}.holiday-shortcuts__card{position:relative;display:block;text-decoration:none;border-radius:26px;overflow:hidden;aspect-ratio:.56;color:#fff;isolation:isolate;box-shadow:0 24px 40px -26px rgba(40,20,10,.6);transition:transform .3s}.holiday-shortcuts__card:hover{transform:translateY(-3px)}.holiday-shortcuts__card:focus-visible{outline:3px solid #C78E66;outline-offset:3px}.holiday-shortcuts__image{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}.holiday-shortcuts__velvet{position:absolute;inset:0;z-index:-2;background:radial-gradient(120% 80% at 50% 10%,#2F5A47 0%,#1C3A2E 55%,#10241B 100%)}.holiday-shortcuts__bokeh{position:absolute;inset:0;z-index:-1;overflow:hidden}.holiday-shortcuts__bokeh i{position:absolute;border-radius:50%;filter:blur(6px);opacity:.35;background:radial-gradient(circle,#FFE7B0,transparent 70%);animation:holiday-breathe 5s ease-in-out infinite}@keyframes holiday-breathe{50%{opacity:.12;transform:scale(1.15)}}.holiday-shortcuts__shade{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(20,10,6,.35) 0%,rgba(20,10,6,0) 30%,rgba(20,10,6,0) 45%,rgba(20,10,6,.7) 78%,rgba(20,10,6,.85))}.holiday-shortcuts__lights{position:absolute;left:0;right:0;top:0;height:18%;pointer-events:none}.holiday-shortcuts__lights svg{width:100%;height:100%;display:block;overflow:visible}.holiday-shortcuts__bulb{animation:holiday-twinkle 2.4s ease-in-out infinite}@keyframes holiday-twinkle{0%,100%{opacity:1}50%{opacity:.25}}.holiday-shortcuts__hang{position:absolute;top:0;transform-origin:50% 0;will-change:transform;pointer-events:none}.holiday-shortcuts__hang svg{display:block;width:100%;height:auto;overflow:visible}.holiday-shortcuts__glow{animation:holiday-flicker 2.2s ease-in-out infinite}@keyframes holiday-flicker{0%,100%{opacity:.95}40%{opacity:.6}60%{opacity:.85}}.holiday-shortcuts__sheen{animation:holiday-sheen 4.5s ease-in-out infinite}@keyframes holiday-sheen{0%,100%{transform:translate(-10px,-6px);opacity:.15}50%{transform:translate(6px,2px);opacity:.75}}.holiday-shortcuts__body{position:absolute;left:0;right:0;bottom:0;padding:.9rem .9rem 1rem}.holiday-shortcuts__code{display:inline-block;font-size:.66rem;font-weight:600;letter-spacing:.16em;padding:.28rem .55rem;border-radius:999px;margin-bottom:.45rem;backdrop-filter:blur(4px)}.holiday-shortcuts__card--holiday .holiday-shortcuts__code{background:rgba(233,133,58,.28);color:#FFC48A}.holiday-shortcuts__card--tree .holiday-shortcuts__code{background:rgba(226,174,132,.22);color:#F0C79E}.holiday-shortcuts h3{margin:0;font-family:"Lora",var(--font-serif),serif;font-weight:500;font-size:clamp(1rem,4.2vw,1.35rem);line-height:1.2;text-shadow:0 2px 10px rgba(0,0,0,.4)}.holiday-shortcuts p{margin:.25rem 0 .45rem;font-family:"Lora",var(--font-serif),serif;font-style:italic;font-size:clamp(.78rem,3.2vw,.92rem);line-height:1.35;opacity:.95}.holiday-shortcuts__go{font-size:.78rem;font-weight:600;letter-spacing:.06em}.holiday-shortcuts__card--holiday .holiday-shortcuts__go{color:#FFC48A}.holiday-shortcuts__card--tree .holiday-shortcuts__go{color:#F0C79E}.holiday-shortcuts__note{margin-top:1.6rem;text-align:center;font-family:"Lora",var(--font-serif),serif;font-style:italic;font-size:.9rem;color:#A8714E}@media (prefers-reduced-motion:reduce){.holiday-shortcuts *{animation:none!important;transition:none!important}}
