<script>
const red=matchMedia('(prefers-reduced-motion: reduce)').matches,CH='ABCDEGHIKLMNOPQRSTUVXY';
const ck=document.getElementById('clock');const tk=()=>ck.textContent=new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'});tk();setInterval(tk,30000);
/* barcode */
const bars=document.getElementById('bars');for(let i=0;i<34;i++){const b=document.createElement('i');b.style.width=[1,1,2,3][Math.floor(Math.random()*4)]+'px';bars.appendChild(b)}
/* reveal & map draw */
if(!('IntersectionObserver' in window))document.querySelectorAll('.reveal,.mapsec').forEach(el=>el.classList.add('in'));
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.15});
document.querySelectorAll('.reveal,.mapsec').forEach(el=>io.observe(el));
setTimeout(()=>document.querySelectorAll('.reveal,.mapsec').forEach(el=>{const r=el.getBoundingClientRect();if(r.top<innerHeight)el.classList.add('in')}),100);
/* scratch card */
(function(){const cv=document.getElementById('scv'),wrap=document.getElementById('scratch');const c=cv.getContext('2d');let drawing=false,done=false;
 function paint(){const r=wrap.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=r.width*dpr;cv.height=r.height*dpr;c.setTransform(dpr,0,0,dpr,0,0);
  const g=c.createLinearGradient(0,0,r.width,r.height);g.addColorStop(0,'#CFC6BE');g.addColorStop(.5,'#EDE6E0');g.addColorStop(1,'#BDB3AA');c.globalCompositeOperation='source-over';c.fillStyle=g;c.fillRect(0,0,r.width,r.height);
  c.fillStyle='rgba(120,100,90,.55)';c.font='600 38px "Josefin Sans",sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('? ? ?',r.width/2,r.height/2-8);
  c.font='14px "Josefin Sans",sans-serif';c.fillText('CÀO ĐỂ KHÁM PHÁ',r.width/2,r.height/2+28)}
 paint();addEventListener('resize',()=>{if(!done)paint()});
 function sc(e){if(!drawing)return;const r=cv.getBoundingClientRect();c.globalCompositeOperation='destination-out';c.beginPath();c.arc(e.clientX-r.left,e.clientY-r.top,22,0,7);c.fill()}
 cv.addEventListener('pointerdown',e=>{drawing=true;cv.setPointerCapture(e.pointerId);sc(e)});cv.addEventListener('pointermove',sc);
 cv.addEventListener('pointerup',()=>{drawing=false;const d=c.getImageData(0,0,cv.width,cv.height).data;let t=0;for(let i=3;i<d.length;i+=64)if(d[i]===0)t++;
  if(t/(d.length/64)>.45){done=true;cv.style.transition='opacity .6s';cv.style.opacity=0;setTimeout(()=>cv.remove(),700)}});
 cv.tabIndex=0;cv.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();cv.remove()}});
 if(red){cv.remove()}})();
</script>
<script>
/* Seasonal shortcut decorations from loi-tat-mua-le.html. */
(function () {
  const root = document.querySelector('.holiday-shortcuts');
  if (!root) return;
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const days = date => Math.max(0, Math.ceil((new Date(date + 'T23:59:59') - new Date()) / 864e5));
  root.querySelector('#halloweenCountdown').textContent = days('2026-10-31');
  root.querySelector('#treeCountdown').textContent = days('2026-12-25');
  const lights = (id, colors) => {
    const svg = root.querySelector('#' + id);
    let html = '<path d="M-5 6 Q50 30 100 12 T205 8" fill="none" stroke="#2A1D16" stroke-width="1.2" vector-effect="non-scaling-stroke"/>';
    for (let i = 0; i < 9; i++) {
      const t = (i + .5) / 9, x = -5 + t * 210;
      const y = t < .5 ? 6 * (1 - 2 * t) ** 2 + 2 * (2 * t) * (1 - 2 * t) * 30 + (2 * t) ** 2 * 12 : 12 * (2 - 2 * t) ** 2 + 2 * (2 * t - 1) * (2 - 2 * t) * -6 + (2 * t - 1) ** 2 * 8;
      const color = colors[i % colors.length];
      html += `<g class="holiday-shortcuts__bulb" style="animation-delay:${(-i * .37).toFixed(2)}s"><ellipse cx="${x}" cy="${y + 4}" rx="2.4" ry="3.6" fill="${color}"/><ellipse cx="${x}" cy="${y + 4}" rx="7" ry="8" fill="${color}" opacity=".25"/></g>`;
    }
    svg.innerHTML = html;
  };
  lights('holidayLights', ['#FFB25B', '#FFD58A', '#E9853A']);
  lights('treeLights', ['#FFE7B0', '#FFF4D6', '#F2D48A']);
  const lantern = id => `<svg viewBox="0 0 40 70"><defs><radialGradient id="lantern${id}" cx="45%" cy="55%" r="60%"><stop offset="0" stop-color="#FFE08A"/><stop offset=".5" stop-color="#F59A3E"/><stop offset="1" stop-color="#C2571C"/></radialGradient></defs><path d="M20 22c-12 4-17 18-13 30 3 9 9 14 13 16 4-2 10-7 13-16 4-12-1-26-13-30z" fill="url(#lantern${id})"/><path d="M20 22c-5 6-6 26 0 46M20 22c5 6 6 26 0 46M20 22c-10 6-12 26-6 42M20 22c10 6 12 26 6 42" stroke="#B85A1E" stroke-width=".9" fill="none" opacity=".7"/><ellipse class="holiday-shortcuts__glow" cx="20" cy="46" rx="9" ry="12" fill="#FFF1B8" opacity=".55"/></svg>`;
  const leaf = color => `<svg viewBox="0 0 40 40"><path d="M20 4l4 9 8-3-3 8 8 3-8 4 3 8-8-2-4 9-4-9-8 2 3-8-8-4 8-3-3-8 8 3z" fill="${color}"/><path d="M20 12v24" stroke="#5E2E16" stroke-width="1"/></svg>`;
  const bauble = (id, light, dark) => `<svg viewBox="0 0 50 62"><defs><radialGradient id="bauble${id}" cx="35%" cy="35%" r="70%"><stop offset="0" stop-color="${light}"/><stop offset="1" stop-color="${dark}"/></radialGradient><clipPath id="clip${id}"><circle cx="25" cy="37" r="21"/></clipPath></defs><rect x="19" y="10" width="12" height="7" rx="2" fill="#D9B36A"/><circle cx="25" cy="8.5" r="3" fill="none" stroke="#D9B36A" stroke-width="1.6"/><circle cx="25" cy="37" r="21" fill="url(#bauble${id})"/><g clip-path="url(#clip${id})"><ellipse class="holiday-shortcuts__sheen" cx="17" cy="28" rx="7" ry="11" fill="#fff" transform="rotate(25 17 28)"/></g></svg>`;
  const star = '<svg viewBox="0 0 50 50"><path d="M25 3l6.2 13.6 14.8 1.7-11 10 3 14.7L25 35.6 12 43l3-14.7-11-10 14.8-1.7z" fill="#E8C274" stroke="#9C6E2E" stroke-width="1"/><path class="holiday-shortcuts__sheen" d="M25 9l3 7" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg>';
  const pumpkin = '<svg viewBox="0 0 50 60"><path d="M25 13c-14 0-21 11-18 25 2 11 10 17 18 17s16-6 18-17c3-14-4-25-18-25z" fill="#e87928" stroke="#8c351b" stroke-width="1.5"/><path d="M25 13V6l6-4" fill="none" stroke="#638044" stroke-width="3" stroke-linecap="round"/><path d="M25 15c-5 9-5 26 0 38M16 18c-4 9-3 23 2 32M34 18c4 9 3 23-2 32" fill="none" stroke="#b94d20" stroke-width="1.2"/><path d="M17 33l5-4 3 4 3-4 5 4-3 7H20z" fill="#29131a"/></svg>';
  const bat = '<svg viewBox="0 0 60 38"><path d="M3 18c8-8 14-7 21 0 2-6 5-8 6-8s4 2 6 8c7-7 13-8 21 0-6 1-8 6-9 13-5-2-10-1-18 4-8-5-13-6-18-4-1-7-3-12-9-13z" fill="#190d20" stroke="#b979c4" stroke-width="1"/></svg>';
  const hanging = [];
  const build = (id, items) => {
    const box = root.querySelector('#' + id), card = box.closest('.holiday-shortcuts__card');
    items.forEach(([left, length, width, art], index) => {
      const item = document.createElement('div');
      item.className = 'holiday-shortcuts__hang'; item.style.left = `calc(${left}% - ${width / 2}%)`; item.style.width = width + '%';
      item.innerHTML = `<div class="holiday-thread" style="width:1px;margin:0 auto;background:linear-gradient(#2A1D16,#7A5A40);height:0"></div>${art}`;
      box.appendChild(item); hanging.push({item, length, phase:index * 1.21, card});
    });
  };
  build('holidayDecor', [[12,16,15,lantern(1)],[30,26,10,leaf('#B5562F')],[48,12,17,lantern(2)],[66,30,9,leaf('#D08A2E')],[80,20,14,lantern(3)]]);
  build('treeDecor', [[10,18,17,bauble(1,'#F3D3B5','#B07A52')],[30,30,14,bauble(2,'#FFF7EC','#D9C2A8')],[50,12,19,star],[70,26,15,bauble(3,'#FFE7A8','#B8863E')],[86,16,12,bauble(4,'#E7B7A3','#8E3F2E')]]);
  build('halloweenDecor', [[12,19,18,pumpkin],[31,9,19,bat],[52,25,16,pumpkin],[72,12,17,bat],[87,28,14,pumpkin]]);
  const resize = () => hanging.forEach(({item, length, card}) => item.querySelector('.holiday-thread').style.height = card.clientHeight * length / 100 + 'px');
  resize(); addEventListener('resize', resize);
  const bokeh = root.querySelector('#treeBokeh');
  for (let i = 0; i < 14; i++) { const dot = document.createElement('i'), size = 10 + Math.random() * 30; dot.style.width = dot.style.height = size + 'px'; dot.style.left = Math.random() * 95 + '%'; dot.style.top = Math.random() * 70 + '%'; dot.style.animationDelay = -Math.random() * 5 + 's'; bokeh.appendChild(dot); }
  if (reduced) return;
  let energy = 0, lastY = scrollY, start = performance.now();
  addEventListener('scroll', () => { energy = Math.min(14, energy + Math.abs(scrollY - lastY) * .12); lastY = scrollY; }, {passive:true});
  root.querySelectorAll('.holiday-shortcuts__card').forEach(card => card.addEventListener('pointerenter', () => energy = Math.min(14, energy + 6)));
  const animate = now => { energy *= .985; const time = (now - start) / 1000; hanging.forEach(({item, phase}) => item.style.transform = `rotate(${(4 + energy) * Math.sin(time * 2 + phase)}deg)`); requestAnimationFrame(animate); };
  requestAnimationFrame(animate);
})();
</script>
<script>
const LNT_HOME = @json($homeData, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
const lntSetLink = (node, href) => { if (node && href) node.href = href; };

const headerLinks = document.querySelectorAll('header.nav .icons a');
lntSetLink(headerLinks[0], LNT_HOME.links.products);
lntSetLink(headerLinks[1], LNT_HOME.links.cart);
lntSetLink(headerLinks[2], LNT_HOME.links.account);
lntSetLink(document.querySelector('header.nav nav a:nth-of-type(4)'), LNT_HOME.links.about);

const arrivalStatusLabels = {landed: 'ĐÃ HẠ CÁNH', flying: 'ĐANG BAY', pre: 'MỞ ĐẶT TRƯỚC'};
const fallbackArrivals = [
  {name: 'Hồng Freedom', origin: 'Ecuador', code: 'UIO', status_key: 'landed', url: '#', image: ''},
  {name: 'Mẫu đơn', origin: 'New Zealand', code: 'CHC', status_key: 'flying', url: '#', image: ''},
  {name: 'Tulip', origin: 'Hà Lan', code: 'AMS', status_key: 'pre', url: '#', image: ''},
  {name: 'Mao lương', origin: 'Côn Minh', code: 'KMG', status_key: 'landed', url: '#', image: ''},
];
const arrivalCode = (code) => [...(code || 'LNT')].map((character) => `<span class="f" data-c="${character}">${red ? character : ''}</span>`).join('');
document.querySelectorAll('.hero .board').forEach((board, index) => { if (index > 0) board.remove(); });
const arrivals = document.querySelector('.hero .board #arrivals');
if (arrivals) {
  const arrivalProducts = (LNT_HOME.products?.length ? LNT_HOME.products : fallbackArrivals).slice(0, 4);
  arrivals.replaceChildren(...arrivalProducts.map((product) => {
    const row = document.createElement('a');
    const statusClass = Object.prototype.hasOwnProperty.call(arrivalStatusLabels, product.status_key) ? product.status_key : 'landed';
    const statusText = arrivalStatusLabels[statusClass] || arrivalStatusLabels.landed;
    row.className = 'brow';
    row.href = product.url;
    if (product.image) row.dataset.image = product.image;
    row.innerHTML = '<span class="cells">' + arrivalCode(product.code) + '<span class="f" style="background:transparent">→</span>' + arrivalCode('HAN') + '</span>'
      + '<span class="fl"></span><span class="st ' + statusClass + '">' + statusText + '</span>';
    row.querySelector('.fl').textContent = product.name + ' · ' + product.origin;
    return row;
  }));
  if (!red) document.querySelectorAll('#arrivals .f[data-c]').forEach((slot) => {
    let attempts = 8 + Math.floor(Math.random() * 8);
    (function resolve() {
      if (attempts-- <= 0) { slot.textContent = slot.dataset.c; return; }
      slot.textContent = CH[Math.floor(Math.random() * CH.length)];
      setTimeout(resolve, 60);
    })();
  });
}

const collectionCodes = ['DLI', 'AMS', 'UIO', 'KMG', 'CHC', 'CPT', 'CTS', 'KUL', 'BOG'];
document.querySelectorAll('.cols .col').forEach((card, index) => {
  const category = LNT_HOME.categories?.[index];
  if (!category) { card.hidden = true; return; }
  lntSetLink(card, category.url);
  const image = card.querySelector('img');
  if (image) { image.src = category.image; image.alt = category.name; }
  card.querySelector('.stamp').textContent = collectionCodes[index];
  card.querySelector('h3').textContent = category.name;
  card.querySelector('small').textContent = category.count + ' sản phẩm';
});

document.querySelectorAll('#journal .mag').forEach((card, index) => {
  const post = LNT_HOME.posts?.[index];
  if (!post) { card.hidden = true; return; }
  lntSetLink(card, post.url);
  const image = card.querySelector('img');
  if (image) { image.src = post.image; image.alt = post.title; }
  card.querySelector('h3').textContent = post.title;
  card.querySelector('p').textContent = post.excerpt + ' →';
});

const prototypeLinks = document.querySelectorAll('footer a');
prototypeLinks.forEach(link => {
  if (link.textContent.includes('Hàng mới hạ cánh')) lntSetLink(link, LNT_HOME.links.products);
  if (link.textContent.includes('LNT Journal')) lntSetLink(link, LNT_HOME.links.blog);
  if (link.textContent.includes('Đối tác B2B')) lntSetLink(link, LNT_HOME.links.b2c);
});
lntSetLink(document.querySelector('#journal .more a'), LNT_HOME.links.blog);
lntSetLink(document.querySelector('#map .btn'), LNT_HOME.links.about);
lntSetLink(document.querySelector('#b2b .btn'), LNT_HOME.links.b2c);

const heroImage = document.querySelector('.hero-img img');
const defaultImage = heroImage?.src || '';

const arrivalsEl = document.querySelector('#arrivals');
if (heroImage && arrivalsEl) {
  let slideshowTimer = null;
  let slideshowIndex = 0;
  let isPaused = false;

  const allRows = arrivalsEl.querySelectorAll('a.brow');
  const slideshowRows = Array.from(allRows).filter(r => r.dataset.image);

  const applySlide = (src, activeRow) => {
    heroImage.style.opacity = '0';
    setTimeout(() => { heroImage.src = src; heroImage.style.opacity = '1'; }, 200);
    allRows.forEach(r => r.classList.toggle('is-active', r === activeRow));
  };

  const advanceSlide = () => {
    if (slideshowRows.length === 0) return;
    slideshowIndex = (slideshowIndex + 1) % slideshowRows.length;
    const row = slideshowRows[slideshowIndex];
    applySlide(row.dataset.image, row);
  };

  const startSlideshow = () => {
    clearInterval(slideshowTimer);
    slideshowTimer = setInterval(advanceSlide, 3000);
  };

  arrivalsEl.addEventListener('mouseover', (e) => {
    const brow = e.target.closest('a.brow');
    if (brow?.dataset.image) { isPaused = true; applySlide(brow.dataset.image, brow); clearInterval(slideshowTimer); }
  });
  arrivalsEl.addEventListener('focusin', (e) => {
    const brow = e.target.closest('a.brow');
    if (brow?.dataset.image) { isPaused = true; applySlide(brow.dataset.image, brow); clearInterval(slideshowTimer); }
  });
  arrivalsEl.addEventListener('mouseout', (e) => {
    if (!e.relatedTarget?.closest('#arrivals')) { isPaused = false; startSlideshow(); }
  });
  arrivalsEl.addEventListener('focusout', (e) => {
    if (!e.relatedTarget?.closest('#arrivals')) { isPaused = false; startSlideshow(); }
  });

  // Start auto-slideshow
  if (slideshowRows.length > 0) {
    applySlide(slideshowRows[0].dataset.image, slideshowRows[0]);
    startSlideshow();
  }
}
</script>
@endpush
